import{_ as a,c as o,a0 as d,o as i}from"./chunks/framework.B6JXc2q-.js";const u=JSON.parse('{"title":"ADR-0005: 统一事件模型","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0005-event-model.md","filePath":"adr/0005-event-model.md"}'),l={name:"adr/0005-event-model.md"};function c(t,e,r,s,n,h){return i(),o("div",null,e[0]||(e[0]=[d('<h1 id="adr-0005-统一事件模型" tabindex="-1">ADR-0005: 统一事件模型 <a class="header-anchor" href="#adr-0005-统一事件模型" aria-label="Permalink to &quot;ADR-0005: 统一事件模型&quot;">​</a></h1><h2 id="状态-已撤回-2026-09-28" tabindex="-1">状态：已撤回（2026-09-28） <a class="header-anchor" href="#状态-已撤回-2026-09-28" aria-label="Permalink to &quot;状态：已撤回（2026-09-28）&quot;">​</a></h2><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><p>2026-05 的设计希望把全部状态变化迁入统一事件模型，并引入约二十种标准事件、统一 payload schema、版本管理、<code>play_id</code> 与 replay 能力。</p><p>该方案没有完成实施。当前 <code>xiaomusic/events.py</code> 只有：</p><ul><li><code>CONFIG_CHANGED</code></li><li><code>DEVICE_CONFIG_CHANGED</code></li><li><code>PLAYER_STATE_CHANGED</code></li></ul><p>播放、认证、Source 和 relay 的状态仍由各自权威模块维护。仓库中不存在原设计要求的标准事件类、事件版本注册、event replay 或 <code>play_id</code> 链路。</p><h2 id="撤回决定" tabindex="-1">撤回决定 <a class="header-anchor" href="#撤回决定" aria-label="Permalink to &quot;撤回决定&quot;">​</a></h2><p>ADR-0005 不再作为现行架构约束。当前规则为：</p><ol><li>EventBus 只承担已有的轻量通知，不是业务状态权威；</li><li>不要求所有状态变化先发布事件；</li><li>不宣称存在未实现的事件 schema、replay、<code>play_id</code> 或 snapshot 端点；</li><li>如果未来重新引入完整事件模型，必须以新的 ADR 明确范围、迁移路径和可执行测试。</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>删除未实现的 <code>event-model.md</code>、<code>correlation-id.md</code> 与 <code>observability.md</code> 设计稿，避免它们继续被误读为当前规范；历史内容仍可从 Git 记录查阅。</li><li><code>constraints.md</code> 与 <code>state-authority.md</code> 改为描述当前真实 ownership。</li><li>现有三个通知事件继续保留，因为配置保存和播放器 SSE 实际依赖它们。</li></ul><h2 id="判断依据" tabindex="-1">判断依据 <a class="header-anchor" href="#判断依据" aria-label="Permalink to &quot;判断依据&quot;">​</a></h2><ul><li>实现：<code>xiaomusic/events.py</code></li><li>发布与订阅点：<code>xiaomusic/xiaomusic.py</code>、<code>xiaomusic/music_library.py</code>、<code>xiaomusic/device_player.py</code>、<code>xiaomusic/api/routers/v1.py</code></li><li>全仓库不存在旧方案中的 <code>PLAY_REQUESTED</code>、<code>SOURCE_RESOLVED</code>、<code>AUTH_RESTORED</code> 与 <code>/api/v1/debug/snapshot</code></li></ul>',14)]))}const m=a(l,[["render",c]]);export{u as __pageData,m as default};
